const questions = [
  { question: 'Qual é a reação mais comum ao receber um convite para uma reunião?', options: ['Aceitar sem ler', 'Sugerir outro horário', 'Fingir que não viu', 'Mandar um \"rapidinho?\"'], correct: 1 },
  { question: 'Qual destes é o superpoder secreto de um time CMS?', options: ['Domar planilhas', 'Publicar antes do café', 'Achar a vírgula perdida', 'Todos os anteriores'], correct: 3 },
  { question: 'O que significa uma mensagem marcada como \"urgente\" às 17:58?', options: ['Amanhã cedo', 'Só uma ideia', 'Provavelmente uma aventura', 'Hora de chamar o jurídico'], correct: 2 },
  { question: 'Qual é a unidade oficial de tempo para aprovar uma pauta?', options: ['1 café', '2 abas abertas', '3 comentários', 'Depende do GIF'], correct: 3 },
  { question: 'O melhor ingrediente de uma boa apresentação é...', options: ['Muitas transições', 'Uma história clara', 'Fonte tamanho 9', '42 gráficos'], correct: 1 }
];

let html = `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The Big CMS Game</title><style>
@import url('https://fonts.googleapis.com/css2?family=Archivo+Black&family=DM+Mono:wght@400;500&family=Manrope:wght@500;700;800&display=swap');
:root{--ink:#12142c;--lime:#d8ff4d;--pink:#ff4f9b;--sky:#63d9ff;--paper:#fff9e8;--purple:#7646ef}*{box-sizing:border-box}body{margin:0;background:var(--ink);color:var(--paper);font-family:Manrope,Arial,sans-serif;min-height:100vh;overflow-x:hidden}body:before,body:after{content:'';position:fixed;border-radius:50%;filter:blur(1px);z-index:-1}body:before{width:460px;height:460px;background:#4831a5;top:-220px;right:-120px}body:after{width:330px;height:330px;background:#dd397a;bottom:-160px;left:-130px}.wrap{width:min(760px,92vw);margin:auto;padding:34px 0 50px}.brand{text-align:center;font-family:'Archivo Black';line-height:.85;font-size:clamp(2.2rem,9vw,5.5rem);letter-spacing:-.07em;text-transform:uppercase;color:var(--lime);text-shadow:5px 5px 0 var(--pink)}.brand small{display:block;font-family:'DM Mono';font-size:.19em;letter-spacing:.25em;color:var(--paper);margin:15px 0 32px}.card{background:var(--paper);color:var(--ink);border:4px solid var(--ink);box-shadow:9px 9px 0 var(--lime);border-radius:24px;padding:clamp(22px,6vw,46px)}h1{font-family:'Archivo Black';font-size:clamp(1.8rem,6vw,3.4rem);line-height:.95;letter-spacing:-.05em;margin:0 0 14px}p{font-size:1.05rem;line-height:1.45}.eyebrow,.count{font-family:'DM Mono';font-weight:500;text-transform:uppercase;letter-spacing:.08em}.count{display:inline-block;background:var(--sky);padding:9px 13px;border-radius:99px;font-size:.75rem;color:var(--ink)}input{display:block;width:100%;border:3px solid var(--ink);background:white;border-radius:13px;font:700 1.1rem Manrope;padding:15px;margin:22px 0 12px}button{width:100%;border:3px solid var(--ink);background:var(--pink);color:#fff;padding:15px 18px;border-radius:13px;font:800 1rem Manrope;cursor:pointer;box-shadow:4px 4px 0 var(--ink);transition:transform .12s,box-shadow .12s}button:active{transform:translate(3px,3px);box-shadow:1px 1px 0 var(--ink)}button.alt{background:var(--lime);color:var(--ink)}button.option{color:var(--ink);background:white;text-align:left;margin:10px 0;font-size:1rem}.option b{display:inline-grid;place-items:center;width:28px;height:28px;background:var(--lime);border-radius:50%;margin-right:10px}.option.selected{background:var(--lime)}.hidden{display:none!important}.status{text-align:center;padding:16px;font-weight:800}.fun{font-family:'DM Mono';font-size:.82rem;color:#5b5671}.score{display:flex;justify-content:space-between;align-items:center;padding:12px 0;border-bottom:2px dashed #d6cfbb}.score:first-child{border-top:2px dashed #d6cfbb}.score strong{font-family:'Archivo Black';font-size:1.4rem}.hostbar{display:flex;gap:10px;margin-top:24px}.hostbar button{font-size:.8rem;padding:11px}.answers{font-family:'DM Mono';color:#514b65;margin-top:16px}.burst{font-size:3rem;position:absolute;transform:rotate(-12deg);right:22px;top:18px}.footer{text-align:center;color:#b8b4cb;font-family:'DM Mono';font-size:.72rem;margin-top:25px}.modal{position:fixed;inset:0;background:#12142ce8;display:grid;place-items:center;padding:20px;z-index:3}.modal .card{width:min(440px,100%)}@media(min-width:700px){.hostbar button{width:auto;flex:1}}
</style></head><body><main class="wrap"><div class="brand">THE BIG<br>CMS GAME<small>o quiz que ninguém pediu, mas todos vão ganhar</small></div>
<section class="card" id="app"><div class="status">Carregando a diversão...</div></section><div class="footer">feito para pessoas brilhantes · respostas sem cola, por favor</div></main>
<script>const app=document.getElementById('app');let me=localStorage.cmsPlayer||'',host=location.hash==='#host',state=null;const esc=s=>String(s).replace(/[&<>\"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[m])); async function api(path,method='GET',body){let r=await fetch('/api/'+path,{method,headers:{'content-type':'application/json'},body:body?JSON.stringify(body):undefined});return r.json()}function lobby(){app.innerHTML='<div class="burst">✦</div><span class="eyebrow">sala de espera</span><h1>Chegue chegando.</h1><p>Escolha seu nome de guerra. Sem senha, sem burocracia, apenas glória.</p><div class="count">'+state.players.length+' pessoa'+(state.players.length===1?'':'s')+' na sala</div><input id="name" maxlength="24" placeholder="Ex.: Rainha do Briefing" value="'+esc(localStorage.cmsName||'')+'"><button id="join">Entrar no jogo →</button><p class="fun">Você pode inventar um nome. Só não use o do chefe… ou use.</p>'+(host?hostControls():'');document.getElementById('join').onclick=async()=>{let n=document.getElementById('name').value.trim();if(!n)return;let x=await api('join','POST',{name:n,existing:me});me=x.id;localStorage.cmsPlayer=me;localStorage.cmsName=n;tick()}}function hostControls(){return '<div class="hostbar"><button class="alt" id="start">'+(state.phase==='lobby'?'Começar jogo':'Próxima pergunta')+'</button><button id="reset">Recomeçar</button></div>'}function question(){let q=state.question;let answered=state.answers.includes(me);app.innerHTML='<span class="eyebrow">rodada '+(state.questionIndex+1)+' de '+state.totalQuestions+'</span><h1>'+esc(q.question)+'</h1><p>'+(!me?'Entre com seu nome para responder.':answered?'Resposta enviada. Agora faça cara de quem sabia.':'Seu momento de glória:')+'</p><div id="opts">'+q.options.map((o,i)=>'<button class="option '+(answered?'selected':'')+'" '+(answered?'disabled':'')+' data-i="'+i+'"><b>'+String.fromCharCode(65+i)+'</b>'+esc(o)+'</button>').join('')+'</div><div class="answers">'+state.answerCount+' de '+state.players.length+' respostas entregues</div>'+(host?hostControls():'');if(!answered&&me)document.querySelectorAll('.option').forEach(b=>b.onclick=async()=>{await api('answer','POST',{playerId:me,option:+b.dataset.i});tick()});bindHost()}function scores(){let mine=state.scores.find(x=>x.id===me);app.innerHTML='<div class="burst">★</div><span class="eyebrow">placar final</span><h1>Fim de jogo!</h1><p>'+ (mine?'Você ficou com <b>'+mine.score+' pontos</b>. '+(mine.rank===1?'Lenda absoluta.':'Uma trajetória respeitável.'):'O júri chegou ao veredito.')+'</p><div>'+state.scores.map((x,i)=>'<div class="score"><span>'+(i===0?'👑 ':'' )+esc(x.name)+'</span><strong>'+x.score+'</strong></div>').join('')+'</div>'+(host?hostControls():'');bindHost()}function bindHost(){if(!host)return;let s=document.getElementById('start'),r=document.getElementById('reset');if(s)s.onclick=async()=>{await api('host/next','POST');tick()};if(r)r.onclick=async()=>{await api('host/reset','POST');tick()}}async function tick(){state=await api('state');if(state.phase==='lobby')lobby();else if(state.phase==='question')question();else scores()}tick();setInterval(tick,1400)</script></body></html>`;

html = html
  .replace("state=null;const esc", "state=null,draftName=localStorage.cmsName||'';const esc")
  .replace("esc(localStorage.cmsName||'')", "esc(draftName)")
  .replace("document.getElementById('join').onclick", "document.getElementById('name').oninput=e=>{draftName=e.target.value};document.getElementById('join').onclick")
  .replace("localStorage.cmsName=n;tick()}}function hostControls", "localStorage.cmsName=n;tick()};bindHost()}function hostControls")
  .replace("if(state.phase==='lobby')lobby();else if", "if(state.phase==='lobby'){if(document.getElementById('name')){let c=document.querySelector('.count');if(c)c.textContent=state.players.length+' pessoa'+(state.players.length===1?'':'s')+' na sala'}else lobby()}else if");

function json(data, status=200){return new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json','cache-control':'no-store'}})}
let schemaReady;
async function ensure(db){if(!schemaReady){schemaReady=db.batch([db.prepare('CREATE TABLE IF NOT EXISTS game_state (id INTEGER PRIMARY KEY CHECK (id = 1), phase TEXT NOT NULL DEFAULT \'lobby\', question_index INTEGER NOT NULL DEFAULT 0, round_id INTEGER NOT NULL DEFAULT 0)'),db.prepare('CREATE TABLE IF NOT EXISTS players (id TEXT PRIMARY KEY, name TEXT NOT NULL, score INTEGER NOT NULL DEFAULT 0, joined_at INTEGER NOT NULL)'),db.prepare('CREATE TABLE IF NOT EXISTS answers (player_id TEXT NOT NULL, round_id INTEGER NOT NULL, option_index INTEGER NOT NULL, answered_at INTEGER NOT NULL, PRIMARY KEY (player_id, round_id))'),db.prepare("INSERT OR IGNORE INTO game_state (id,phase,question_index,round_id) VALUES (1,'lobby',0,0)")]).catch(error=>{schemaReady=null;throw error})}await schemaReady}
async function state(db){const game=await db.prepare('SELECT phase, question_index, round_id FROM game_state WHERE id = 1').first();const players=(await db.prepare('SELECT id, name, score FROM players ORDER BY joined_at').all()).results;const answerCount=(await db.prepare('SELECT COUNT(*) AS count FROM answers WHERE round_id = ?').bind(game.round_id).first()).count;const base={phase:game.phase,questionIndex:game.question_index,totalQuestions:questions.length,players,answerCount,answers:(await db.prepare('SELECT player_id FROM answers WHERE round_id = ?').bind(game.round_id).all()).results.map(x=>x.player_id)};if(game.phase==='question')base.question={question:questions[game.question_index].question,options:questions[game.question_index].options};if(game.phase==='scores'){base.scores=(await db.prepare('SELECT id,name,score FROM players ORDER BY score DESC, joined_at ASC').all()).results.map((x,i)=>({...x,rank:i+1}))}return base}
export default {async fetch(req,env){const url=new URL(req.url);if(!url.pathname.startsWith('/api/'))return new Response(html,{headers:{'content-type':'text/html;charset=UTF-8'}});const path=url.pathname.slice(5),db=env.DB;await ensure(db);if(req.method==='GET'&&path==='state')return json(await state(db));let body={};try{body=await req.json()}catch{}if(path==='join'&&req.method==='POST'){let name=String(body.name||'').trim().slice(0,24);if(!name)return json({error:'Nome obrigatório'},400);let id=body.existing||crypto.randomUUID();let exists=await db.prepare('SELECT id FROM players WHERE id = ?').bind(id).first();if(!exists)await db.prepare('INSERT INTO players (id,name,score,joined_at) VALUES (?,?,?,?)').bind(id,name,0,Date.now()).run();else await db.prepare('UPDATE players SET name = ? WHERE id = ?').bind(name,id).run();return json({id})}if(path==='answer'&&req.method==='POST'){let game=await db.prepare('SELECT phase,question_index,round_id FROM game_state WHERE id=1').first(),id=String(body.playerId||''),option=Number(body.option);if(game.phase!=='question'||!Number.isInteger(option)||!id)return json({error:'Resposta indisponível'},400);let player=await db.prepare('SELECT id FROM players WHERE id=?').bind(id).first();if(!player)return json({error:'Jogador não encontrado'},404);let prior=await db.prepare('SELECT player_id FROM answers WHERE player_id=? AND round_id=?').bind(id,game.round_id).first();if(!prior){let correct=questions[game.question_index].correct===option;await db.batch([db.prepare('INSERT INTO answers (player_id,round_id,option_index,answered_at) VALUES (?,?,?,?)').bind(id,game.round_id,option,Date.now()),...(correct?[db.prepare('UPDATE players SET score=score+100 WHERE id=?').bind(id)]:[])]);}return json({ok:true})}if(path==='host/next'&&req.method==='POST'){let g=await db.prepare('SELECT phase,question_index,round_id FROM game_state WHERE id=1').first();if(g.phase==='lobby')await db.prepare("UPDATE game_state SET phase='question',question_index=0,round_id=1 WHERE id=1").run();else if(g.phase==='question'&&g.question_index<questions.length-1)await db.prepare('UPDATE game_state SET question_index=?,round_id=? WHERE id=1').bind(g.question_index+1,g.round_id+1).run();else await db.prepare("UPDATE game_state SET phase='scores' WHERE id=1").run();return json({ok:true})}if(path==='host/reset'&&req.method==='POST'){await db.batch([db.prepare('DELETE FROM answers'),db.prepare('DELETE FROM players'),db.prepare("UPDATE game_state SET phase='lobby',question_index=0,round_id=0 WHERE id=1")]);return json({ok:true})}return json({error:'Não encontrado'},404)}};
